import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from common import PySet
P = PySet()
p = P.p

p("Trailing zeros of factorial", "M", "math", "trailing_zeros", "n", "Return the number of trailing zeros in `n!`.", ["Count factors of 5."],
  "def trailing_zeros(n):\n    count = 0\n    while n:\n        n //= 5\n        count += n\n    return count", "Each zero needs a 2 and a 5; fives are scarcer.", [(5,), (3,)], [(0,), (25,), (100,), (1000,)])
p("Sieve of Eratosthenes", "M", "number-theory", "primes_up_to", "n", "Return all primes less than or equal to `n` in ascending order.", ["Cross out multiples starting from p*p."],
  "def primes_up_to(n):\n    if n < 2:\n        return []\n    sieve = [True] * (n + 1)\n    sieve[0] = sieve[1] = False\n    i = 2\n    while i * i <= n:\n        if sieve[i]:\n            for j in range(i * i, n + 1, i):\n                sieve[j] = False\n        i += 1\n    return [i for i, ok in enumerate(sieve) if ok]", "Linear-ish time sieve.", [(10,), (1,)], [(2,), (30,), (100,), (0,)])
p("Count primes below n", "M", "number-theory", "count_primes_below", "n", "Return the number of primes strictly less than `n`.", ["Use a sieve."],
  "def count_primes_below(n):\n    if n < 3:\n        return 0\n    sieve = [True] * n\n    sieve[0] = sieve[1] = False\n    for i in range(2, int(n ** 0.5) + 1):\n        if sieve[i]:\n            sieve[i * i::i] = [False] * len(range(i * i, n, i))\n    return sum(sieve)", "Slice assignment clears multiples quickly.", [(10,), (2,)], [(0,), (3,), (100,), (1000,)])
p("Modular exponentiation", "M", "number-theory", "mod_pow", "base, exp, mod", "Compute `(base ** exp) % mod` efficiently for non-negative `exp` and `mod >= 1` (no built-in `pow` with three arguments).", ["Square and multiply, reducing each step."],
  "def mod_pow(base, exp, mod):\n    result = 1 % mod\n    base %= mod\n    while exp:\n        if exp & 1:\n            result = result * base % mod\n        base = base * base % mod\n        exp >>= 1\n    return result", "Reduce after every multiplication.", [(2, 10, 1000), (3, 0, 7)], [(5, 3, 13), (7, 100, 1), (2, 1000, 1000007), (10, 9, 6)])
p("Modular inverse", "H", "number-theory", "mod_inverse", "a, m", "Return the multiplicative inverse of `a` modulo `m` (with `gcd(a, m) = 1`, `m > 1`), as a value in `[1, m-1]`.", ["Extended Euclid."],
  "def mod_inverse(a, m):\n    def egcd(x, y):\n        if y == 0:\n            return x, 1, 0\n        g, s, t = egcd(y, x % y)\n        return g, t, s - (x // y) * t\n    _, s, _ = egcd(a % m, m)\n    return s % m", "Bezout coefficients give the inverse.", [(3, 11), (10, 17)], [(1, 2), (7, 40), (5, 18), (123, 1009)])
p("Extended gcd", "H", "number-theory", "extended_gcd", "a, b", "Return `[g, x, y]` where `g = gcd(a, b)` and `a*x + b*y = g`, using the standard recursive extended Euclid algorithm (`extended_gcd(a, 0) = [a, 1, 0]`).", ["Recurse on `(b, a % b)` and adjust coefficients."],
  "def extended_gcd(a, b):\n    if b == 0:\n        return [a, 1, 0]\n    g, x, y = extended_gcd(b, a % b)\n    return [g, y, x - (a // b) * y]", "The coefficients of the smaller problem map back.", [(30, 20), (7, 0)], [(1, 1), (240, 46), (17, 5), (12, 18)])
p("Euler totient", "M", "number-theory", "totient", "n", "Return the count of integers in `1..n` that are coprime to `n`.", ["Multiply by (1 - 1/p) for each prime factor."],
  "def totient(n):\n    result = n\n    m = n\n    p = 2\n    while p * p <= m:\n        if m % p == 0:\n            while m % p == 0:\n                m //= p\n            result -= result // p\n        p += 1\n    if m > 1:\n        result -= result // m\n    return result", "Phi is multiplicative over prime powers.", [(10,), (1,)], [(9,), (36,), (97,), (100,)])
p("Chinese remainder small", "H", "number-theory", "crt_smallest", "remainders, moduli", "Find the smallest non-negative `x` with `x % moduli[i] == remainders[i]` for all i. The moduli are pairwise coprime.", ["Combine congruences one at a time."],
  "def crt_smallest(remainders, moduli):\n    x, step = 0, 1\n    for r, m in zip(remainders, moduli):\n        while x % m != r:\n            x += step\n        step *= m\n    return x", "After each step x satisfies all earlier congruences, so we step by their product.", [([2, 3, 2], [3, 5, 7]), ([0], [5])], [([1, 2], [2, 3]), ([4, 6], [5, 7]), ([0, 0], [3, 4])])
p("Binomial coefficient mod", "H", "combinatorics", "n_choose_k_mod", "n, k, mod", "Return `C(n, k) % mod` where `mod` is a prime larger than `n`.", ["Compute with factorials and a modular inverse via Fermat."],
  "def n_choose_k_mod(n, k, mod):\n    if k < 0 or k > n:\n        return 0\n    num = den = 1\n    for i in range(k):\n        num = num * (n - i) % mod\n        den = den * (i + 1) % mod\n    return num * pow(den, mod - 2, mod) % mod", "Fermat's little theorem gives the inverse.", [(5, 2, 1000003), (10, 0, 1000003)], [(10, 10, 1000003), (52, 5, 1000003), (6, 7, 1009), (30, 15, 1000003)])
p("Catalan number", "M", "combinatorics", "catalan", "n", "Return the n-th Catalan number: `C(0)=1`, `C(n+1)=sum C(i)*C(n-i)`.", ["Build up with the recurrence."],
  "def catalan(n):\n    c = [1] + [0] * n\n    for i in range(1, n + 1):\n        c[i] = sum(c[j] * c[i - 1 - j] for j in range(i))\n    return c[n]", "It counts balanced parentheses, binary trees and more.", [(3,), (0,)], [(1,), (5,), (10,), (15,)])
p("Derangements", "H", "combinatorics", "derangements", "n", "Return the number of permutations of `n` items where nobody stays in their original position.", ["D(n) = (n-1) * (D(n-1) + D(n-2))."],
  "def derangements(n):\n    if n == 0:\n        return 1\n    a, b = 1, 0\n    for i in range(2, n + 1):\n        a, b = b, (i - 1) * (a + b)\n    return b", "A classic recurrence.", [(3,), (1,)], [(0,), (2,), (4,), (10,)])
p("Number of binary strings without consecutive ones", "M", "dynamic-programming", "no_consecutive_ones", "n", "Return how many binary strings of length `n` contain no two adjacent `1`s.", ["Fibonacci recurrence."],
  "def no_consecutive_ones(n):\n    a, b = 1, 2\n    if n == 0:\n        return 1\n    for _ in range(n - 1):\n        a, b = b, a + b\n    return b", "Strings ending in 0 plus strings ending in 01.", [(3,), (1,)], [(0,), (2,), (10,), (20,)])
p("Integer to words", "H", "parsing", "number_to_words", "n", "Convert an integer `0 <= n < 10**9` to English words, e.g. `1234` -> `\"One Thousand Two Hundred Thirty Four\"`. No `and`, words capitalised and separated by single spaces; zero is `\"Zero\"`.", ["Handle chunks of three digits with a scale word."],
  "def number_to_words(n):\n    if n == 0:\n        return 'Zero'\n    ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']\n    tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety']\n    def below_1000(x):\n        words = []\n        if x >= 100:\n            words += [ones[x // 100], 'Hundred']\n            x %= 100\n        if x >= 20:\n            words.append(tens[x // 10])\n            x %= 10\n        if x:\n            words.append(ones[x])\n        return words\n    out = []\n    for scale, name in ((10**6, 'Million'), (1000, 'Thousand'), (1, '')):\n        chunk, n = divmod(n, scale)\n        if chunk:\n            out += below_1000(chunk) + ([name] if name else [])\n    return ' '.join(out)", "Three-digit groups plus a scale name.", [(123,), (1000,)], [(0,), (19,), (20,), (100,), (1234567,), (100000000,), (45,)])
p("Convert to base k", "E", "numbers", "to_base", "n, base", "Return the representation of the non-negative integer `n` in a base from 2 to 16 as a string using digits `0-9A-F` (uppercase). Zero is `\"0\"`.", ["Repeatedly divide by the base."],
  "def to_base(n, base):\n    digits = '0123456789ABCDEF'\n    if n == 0:\n        return '0'\n    out = []\n    while n:\n        n, r = divmod(n, base)\n        out.append(digits[r])\n    return ''.join(reversed(out))", "Remainders are the digits from the right.", [(10, 2), (255, 16)], [(0, 8), (100, 7), (31, 16), (9, 3)])
p("Parse from base k", "E", "numbers", "from_base", "s, base", "Convert the string `s` (digits `0-9A-F`, uppercase) in the given base to an integer, without using `int(s, base)`.", ["Horner's method."],
  "def from_base(s, base):\n    digits = '0123456789ABCDEF'\n    n = 0\n    for c in s:\n        n = n * base + digits.index(c)\n    return n", "Multiply and add per digit.", [("1010", 2), ("FF", 16)], [("0", 10), ("777", 8), ("1A", 16), ("12", 3)])
p("Fraction to decimal", "H", "math", "fraction_to_decimal", "num, den", "Return the decimal expansion of `num / den` as a string; wrap a repeating part in parentheses (e.g. `1/3` -> `\"0.(3)\"`, `2/1` -> `\"2\"`). Handle negative numbers and `den != 0`.", ["Track remainders to detect the cycle."],
  "def fraction_to_decimal(num, den):\n    if num == 0:\n        return '0'\n    sign = '-' if (num < 0) != (den < 0) else ''\n    num, den = abs(num), abs(den)\n    whole, rem = divmod(num, den)\n    if rem == 0:\n        return f'{sign}{whole}'\n    digits, seen = [], {}\n    while rem and rem not in seen:\n        seen[rem] = len(digits)\n        rem *= 10\n        digits.append(str(rem // den))\n        rem %= den\n    if rem:\n        i = seen[rem]\n        return f\"{sign}{whole}.{''.join(digits[:i])}({''.join(digits[i:])})\"\n    return f\"{sign}{whole}.{''.join(digits)}\"", "A repeated remainder means the digits repeat.", [(1, 2), (2, 3)], [(4, 333), (1, 6), (-50, 8), (0, 5), (7, -12), (10, 5)])
p("Add fractions", "M", "math", "add_fractions", "a, b", "Add two fractions given as `[numerator, denominator]` (positive denominators) and return the result in lowest terms as `[numerator, denominator]`.", ["Cross-multiply and divide by the gcd."],
  "def add_fractions(a, b):\n    n = a[0] * b[1] + b[0] * a[1]\n    d = a[1] * b[1]\n    x, y = abs(n), d\n    while y:\n        x, y = y, x % y\n    return [n // x, d // x] if n else [0, 1]", "Reduce at the end with the gcd.", [([1, 2], [1, 3]), ([1, 4], [3, 4])], [([0, 1], [0, 5]), ([-1, 2], [1, 2]), ([2, 6], [3, 9]), ([5, 7], [2, 3])])
p("Multiples of 3 or 5", "E", "math", "sum_of_multiples", "n", "Return the sum of all multiples of 3 or 5 that are below `n`.", ["Loop and test both divisors."],
  "def sum_of_multiples(n):\n    return sum(i for i in range(n) if i % 3 == 0 or i % 5 == 0)", "The classic first Project Euler problem.", [(10,), (1,)], [(0,), (16,), (100,), (1000,)])
p("Ugly check", "E", "math", "is_ugly", "n", "Return whether `n > 0` has only prime factors 2, 3 and 5.", ["Divide out 2, 3, 5."],
  "def is_ugly(n):\n    if n <= 0:\n        return False\n    for f in (2, 3, 5):\n        while n % f == 0:\n            n //= f\n    return n == 1", "What is left must be 1.", [(6,), (14,)], [(1,), (0,), (-6,), (30,), (49,)])
p("Count digit occurrences up to n", "H", "math", "count_digit_one", "n", "Return how many times the digit `1` appears in all numbers from 1 to `n` inclusive.", ["Count per digit position."],
  "def count_digit_one(n):\n    total = 0\n    m = 1\n    while m <= n:\n        high, cur, low = n // (m * 10), n // m % 10, n % m\n        if cur == 0:\n            total += high * m\n        elif cur == 1:\n            total += high * m + low + 1\n        else:\n            total += (high + 1) * m\n        m *= 10\n    return total", "Analyse each decimal position independently.", [(13,), (0,)], [(1,), (10,), (99,), (100,), (1234,)])
p("Armstrong numbers in range", "M", "numbers", "armstrong_in_range", "lo, hi", "Return the Armstrong numbers (each equals the sum of its digits to the power of the digit count) between `lo` and `hi` inclusive.", ["Test each number."],
  "def armstrong_in_range(lo, hi):\n    out = []\n    for n in range(lo, hi + 1):\n        s = str(n)\n        if sum(int(c) ** len(s) for c in s) == n:\n            out.append(n)\n    return out", "Brute force is fine for small ranges.", [(100, 500), (1, 9)], [(500, 1000), (0, 0), (9000, 9999)])
p("Sum of two squares", "M", "math", "is_sum_of_two_squares", "n", "Return whether the non-negative integer `n` can be written as `a*a + b*b` with integers `a, b >= 0`.", ["Two pointers from 0 and sqrt(n)."],
  "def is_sum_of_two_squares(n):\n    a, b = 0, int(n ** 0.5) + 1\n    while a <= b:\n        s = a * a + b * b\n        if s == n:\n            return True\n        if s < n:\n            a += 1\n        else:\n            b -= 1\n    return False", "Two-pointer search over squares.", [(5,), (3,)], [(0,), (1,), (25,), (13,), (1000,), (999,)])
p("Pythagorean triplets up to n", "M", "math", "pythagorean_triples", "n", "Return all triples `[a, b, c]` with `a < b < c <= n` and `a*a + b*b == c*c`, sorted ascending.", ["Loop a and b, test c."],
  "def pythagorean_triples(n):\n    out = []\n    for a in range(1, n + 1):\n        for b in range(a + 1, n + 1):\n            c2 = a * a + b * b\n            c = int(c2 ** 0.5)\n            if c <= n and c * c == c2:\n                out.append([a, b, c])\n    return out", "Check perfect squares for c.", [(13,), (4,)], [(5,), (20,), (30,)])
p("Number of trailing zeros in binary", "E", "bit-manipulation", "trailing_zero_bits", "n", "Return the number of trailing zero bits in the positive integer `n`.", ["`n & -n` isolates the lowest set bit."],
  "def trailing_zero_bits(n):\n    return (n & -n).bit_length() - 1", "The position of the lowest set bit.", [(8,), (7,)], [(1,), (12,), (1024,), (96,)])
p("Largest power of two not above n", "E", "bit-manipulation", "highest_power_of_two", "n", "Return the largest power of two that is less than or equal to `n >= 1`.", ["`1 << (n.bit_length() - 1)`."],
  "def highest_power_of_two(n):\n    return 1 << (n.bit_length() - 1)", "Bit length gives the top bit.", [(10,), (1,)], [(2,), (63,), (64,), (1000,)])
p("Reverse integer 32-bit", "M", "numbers", "reverse_signed", "x", "Reverse the digits of a signed integer; return 0 if the result leaves the 32-bit signed range `[-2**31, 2**31 - 1]`.", ["Handle the sign separately."],
  "def reverse_signed(x):\n    sign = -1 if x < 0 else 1\n    r = sign * int(str(abs(x))[::-1])\n    return r if -2**31 <= r <= 2**31 - 1 else 0", "Check the range at the end.", [(123,), (-120,)], [(0,), (1534236469,), (-2147483648,), (900000,)])
p("Palindrome pairs count", "H", "strings", "count_palindrome_pairs", "words", "Count index pairs `i < j` such that `words[i] + words[j]` or `words[j] + words[i]` is a palindrome (count the pair once if either holds).", ["Brute force over pairs with a palindrome test."],
  "def count_palindrome_pairs(words):\n    def pal(s):\n        return s == s[::-1]\n    return sum(1 for i in range(len(words)) for j in range(i + 1, len(words)) if pal(words[i] + words[j]) or pal(words[j] + words[i]))", "Quadratic but clear.", [(['abcd', 'dcba', 'lls', 's', 'sssll'],), (['a', 'b'],)], [([],), (['a', ''],), (['ab', 'ba', 'a'],)])
p("Longest common prefix of many by sorting", "E", "strings", "common_prefix_sorted", "words", "Return the longest common prefix of a non-empty list by comparing only the lexicographically smallest and largest word.", ["After sorting only the extremes matter."],
  "def common_prefix_sorted(words):\n    a, b = min(words), max(words)\n    i = 0\n    while i < len(a) and i < len(b) and a[i] == b[i]:\n        i += 1\n    return a[:i]", "The prefix of the extremes is shared by everything between.", [(['flower', 'flow', 'flight'],), (['dog', 'car'],)], [(['a'],), (['abc', 'abc'],), (['x', 'xy', 'xyz'],)])
p("Multiply large numbers as strings", "H", "strings", "multiply_strings", "a, b", "Multiply two non-negative integers given as decimal strings and return the product as a string, without converting the whole strings to integers.", ["Schoolbook multiplication into an array of digits."],
  "def multiply_strings(a, b):\n    if a == '0' or b == '0':\n        return '0'\n    res = [0] * (len(a) + len(b))\n    for i in range(len(a) - 1, -1, -1):\n        for j in range(len(b) - 1, -1, -1):\n            s = int(a[i]) * int(b[j]) + res[i + j + 1]\n            res[i + j + 1] = s % 10\n            res[i + j] += s // 10\n    return ''.join(map(str, res)).lstrip('0')", "Each digit pair contributes to two result positions.", [("2", "3"), ("123", "456")], [("0", "99"), ("999", "999"), ("1", "1"), ("12345678901234567890", "98765432109876543210")])
p("Add large numbers as strings", "M", "strings", "add_strings", "a, b", "Add two non-negative decimal integers given as strings; return the sum as a string without converting the whole strings to ints.", ["Add digit by digit from the right with a carry."],
  "def add_strings(a, b):\n    i, j, carry = len(a) - 1, len(b) - 1, 0\n    out = []\n    while i >= 0 or j >= 0 or carry:\n        s = carry\n        if i >= 0:\n            s += int(a[i]); i -= 1\n        if j >= 0:\n            s += int(b[j]); j -= 1\n        out.append(str(s % 10))\n        carry = s // 10\n    return ''.join(reversed(out))", "Grade-school addition.", [("11", "123"), ("456", "77")], [("0", "0"), ("999", "1"), ("1", "99999")])
